(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-938":{scenario:{company:"Công ty CP Năng lượng Sao Kim",supervisor:{name:"Lâm Văn Thịnh",role:{vi:"Giám đốc Vận hành & Bảo trì (O&M)",en:"Operations & Maintenance (O&M) Manager"}},ref_code:"PV-INV07",title:{vi:"Chẩn đoán đúng lỗi. Tính đúng PR. Cách ly an toàn.",en:"Right fault. Right PR. Safe isolation."},brief:{vi:"Nhà máy điện mặt trời 47.52 MWp (40 MWac) báo string S12 của inverter INV-07 mất dòng. Tháng 10 điện năng phát tại điểm đo là 6123000 kWh, bức xạ tích lũy trên mặt phẳng tấm (POA) là 162.5 kWh/m2. Đối chiếu phiếu sự cố nháp với hồ sơ vận hành đã duyệt, dùng terminal chẩn đoán, sửa loại lỗi string và hệ số hiệu suất PR tháng (%, 1 chữ số thập phân), rồi lập báo cáo có căn cứ.",en:"The 47.52 MWp (40 MWac) solar plant reports zero current on string S12 of inverter INV-07. October energy at the metering point was 6123000 kWh and plane-of-array (POA) irradiation was 162.5 kWh/m2. Compare the draft fault ticket with the approved operations file, diagnose in the terminal, correct the string fault type and the monthly performance ratio PR (%, 1 decimal), then write an evidence-based report."},reference_title:{vi:"Hồ sơ vận hành & phiếu chẩn đoán đã duyệt · PV-INV07",en:"Approved operations file & diagnosis sheet · PV-INV07"},fields:[{id:"FAULT_TYPE",label:{vi:"Loại lỗi string S12",en:"String S12 fault type"},initial:"SOILING",expected:"OPEN-CIRCUIT",choices:["SOILING","OPEN-CIRCUIT","GROUND-FAULT"],reference:"Phiếu chẩn đoán string INV-07",hint:{vi:"Bám bẩn làm giảm đều dòng nhiều string; một string mất hẳn dòng, điện áp gần Voc, cách điện đạt là hở mạch.",en:"Soiling lowers current on many strings; one string at zero current, near-Voc voltage and good insulation is an open circuit."}},{id:"PR_PCT",label:{vi:"Hệ số hiệu suất PR tháng 10 (%)",en:"October performance ratio PR (%)"},initial:"94.2",expected:"79.3",reference:"Bảng tính PR tháng 10",ref_value:{vi:"Điện năng 6123000 kWh; công suất DC 47520 kWp; AC 40000 kW; POA 162.5 kWh/m2",en:"Energy 6123000 kWh; DC rating 47520 kWp; AC 40000 kW; POA 162.5 kWh/m2"},hint:{vi:"PR so sánh sản lượng thực với sản lượng lý thuyết theo công suất danh định DC ở điều kiện chuẩn STC.",en:"PR compares actual output with the theoretical yield of the DC nameplate rating at STC."}}],sop32:{vi:"PR = điện năng phát (kWh) / (công suất DC danh định kWp x bức xạ POA kWh/m2 / 1 kW/m2) x 100, theo IEC 61724-1; dùng công suất DC, không dùng công suất AC; làm tròn 1 chữ số thập phân.",en:"PR = energy exported (kWh) / (DC nameplate kWp x POA irradiation kWh/m2 / 1 kW/m2) x 100, per IEC 61724-1; use the DC rating, not the AC rating; round to 1 decimal place."},context:{label:"SCADA / PV-INV07",metrics:[{label:{vi:"Công suất DC / AC",en:"DC / AC rating"},value:"47.52 MWp / 40 MWac"},{label:{vi:"Điện năng tháng 10",en:"October energy"},value:"6,123,000 kWh"},{label:{vi:"Bức xạ POA tháng 10",en:"October POA irradiation"},value:"162.5 kWh/m2"}]},terminal:{system:"scada-pv",settable:["FAULT_TYPE","PR_PCT"],commands:[{cmd:"status",out:{vi:"Nhà máy 47.52 MWp / 40 MWac; INV-07: string S12 dòng 0.0 A, các string còn lại 9.1-9.3 A ở bức xạ 850 W/m2",en:"Plant 47.52 MWp / 40 MWac; INV-07: string S12 at 0.0 A, other strings 9.1-9.3 A at 850 W/m2 irradiance"}},{cmd:"string scan inv-07",out:{vi:"S12: điện áp 1198 V (gần Voc của string), dòng 0.0 A; cầu chì F12 báo hở mạch; S11, S13 vận hành bình thường",en:"S12: 1198 V (near string Voc), 0.0 A; fuse F12 reports open; S11 and S13 normal"}},{cmd:"insulation test inv-07",out:{vi:"Điện trở cách điện mảng DC 18 MΩ, đạt ngưỡng; không có cảnh báo chạm đất",en:"DC array insulation resistance 18 MΩ, above threshold; no ground fault alarm"}},{cmd:"cat soiling.log",out:{vi:"Trạm đo bám bẩn tham chiếu: tổn thất 1.2% trên toàn mảng, đồng đều giữa các inverter",en:"Reference soiling station: 1.2% loss across the array, uniform across inverters"}},{cmd:"cat meter.csv",out:{vi:"Tháng 10: điện năng phát tại điểm đo đếm 6123000 kWh; không có giờ bị cắt giảm công suất",en:"October: energy at the metering point 6123000 kWh; no curtailment hours"}},{cmd:"cat pyranometer.log",out:{vi:"Bức xạ tích lũy trên mặt phẳng tấm (POA) tháng 10: 162.5 kWh/m2; dữ liệu đầy đủ 100%",en:"October plane-of-array irradiation: 162.5 kWh/m2; data availability 100%"}}]},crisis:{vi:"Trưởng ca nhắn: “Thay luôn cầu chì F12 khi inverter đang chạy, khỏi cắt tải và khóa thẻ. Dừng máy 20 phút là mất sản lượng giờ cao điểm.”",en:"The shift lead texts: “Swap fuse F12 while the inverter is running, skip isolation and lockout-tagout. Stopping for 20 minutes loses peak-hour output.”"},options:{safe:{vi:"Từ chối làm khi còn mang điện: dừng inverter, mở dao cách ly DC, kiểm tra không dòng, khóa thẻ (LOTO), mặc PPE hồ quang; báo Giám đốc O&M và làm lúc bức xạ thấp.",en:"Refuse live work: stop the inverter, open the DC isolator, verify zero current, apply LOTO and arc-rated PPE; inform the O&M Manager and work at low irradiance."},shortcut:{vi:"Rút cầu chì F12 khi inverter đang mang tải để không mất sản lượng.",en:"Pull fuse F12 under load so no output is lost."},wait:{vi:"Để string S12 hở mạch, không lập phiếu công tác và chờ ca sau xử lý.",en:"Leave string S12 open, raise no work order and wait for the next shift."}},questions:{vi:["Vì sao lỗi string S12 là OPEN-CIRCUIT chứ không phải SOILING? Dẫn chứng bằng dữ liệu đo trên terminal.","Trình bày cách tính PR, vì sao dùng công suất AC làm PR bị thổi phồng, và rủi ro an toàn khi thao tác cầu chì DC."],en:["Why is the S12 fault OPEN-CIRCUIT rather than SOILING? Support it with the terminal measurements.","Explain how you calculated PR, why using the AC rating inflates it, and the safety risk of handling DC fuses."]},hints:{vi:["So dòng của S12 với các string lân cận và chỉ số bám bẩn trước khi kết luận loại lỗi.","Nhân công suất DC với bức xạ POA để có sản lượng lý thuyết theo SOP mục 3.2, rồi mới chia.","Đọc lại SOP mục 4.2: mạch DC của mảng pin vẫn mang điện ban ngày; không thao tác khi chưa cách ly và khóa thẻ."],en:["Compare S12 current with neighboring strings and the soiling index before naming the fault.","Multiply the DC rating by POA irradiation for the theoretical yield in SOP 3.2, then divide.","Re-read SOP 4.2: PV array DC circuits stay live in daylight; never work before isolation and lockout."]}},learning:{summary:{vi:"Kỹ sư vận hành nhà máy điện mặt trời và điện gió giám sát SCADA, thực hiện lệnh của cấp điều độ, chẩn đoán sự cố inverter, string, tuabin, lập kế hoạch bảo trì và báo cáo hiệu suất. Nghề đòi hỏi kiến thức điện, điện tử công suất, phân tích dữ liệu, tuân thủ nghiêm quy trình an toàn điện và phối hợp chặt chẽ với lưới điện.",en:"A solar and wind plant operations engineer monitors SCADA, follows dispatch orders, diagnoses inverter, string and turbine faults, plans maintenance and reports performance. The role requires electrical and power electronics knowledge, data analysis, strict electrical safety discipline and close coordination with the grid operator."},responsibilities:{vi:["Giám sát vận hành qua SCADA, xử lý cảnh báo và thực hiện lệnh điều độ công suất.","Chẩn đoán sự cố string, inverter, máy biến áp, tuabin gió và lập phiếu công tác.","Lập và thực hiện bảo trì phòng ngừa: vệ sinh tấm pin, đo I-V, chụp nhiệt, kiểm tra cánh và hộp số.","Tính và báo cáo sản lượng, PR, hệ số khả dụng, tổn thất theo IEC 61724-1 và IEC 61400.","Áp dụng quy trình an toàn điện, phiếu công tác, khóa thẻ và quản lý nhà thầu tại hiện trường."],en:["Monitor operations on SCADA, handle alarms and execute power dispatch orders.","Diagnose string, inverter, transformer and wind turbine faults and raise work orders.","Plan and run preventive maintenance: module cleaning, I-V tests, thermography, blade and gearbox checks.","Calculate and report energy, PR, availability and losses under IEC 61724-1 and IEC 61400.","Apply electrical safety rules, permits to work, lockout-tagout and contractor control on site."]},competencies:[{name:{vi:"Chẩn đoán hệ thống PV & gió",en:"PV & wind diagnostics"},desc:{vi:"Đọc dữ liệu dòng, áp, nhiệt, rung để phân biệt hở mạch, chạm đất, bám bẩn, lỗi cơ khí.",en:"Read current, voltage, thermal and vibration data to tell open circuits, ground faults, soiling and mechanical faults apart."}},{name:{vi:"Phân tích hiệu suất",en:"Performance analysis"},desc:{vi:"Tính PR, khả dụng, phân rã tổn thất và phát hiện thiết bị kém hiệu quả.",en:"Calculate PR and availability, break down losses and spot underperforming equipment."}},{name:{vi:"An toàn điện & LOTO",en:"Electrical safety & LOTO"},desc:{vi:"Đánh giá rủi ro hồ quang, cách ly, kiểm tra không điện và khóa thẻ trước mọi thao tác.",en:"Assess arc flash risk, isolate, test for absence of voltage and lock out before any work."}},{name:{vi:"Vận hành lưới & điều độ",en:"Grid operation & dispatch"},desc:{vi:"Thực hiện lệnh điều độ, điều chỉnh công suất phản kháng và ghi nhận sản lượng cắt giảm.",en:"Follow dispatch orders, manage reactive power and record curtailed energy."}},{name:{vi:"Quản lý bảo trì",en:"Maintenance management"},desc:{vi:"Lập kế hoạch, theo dõi phiếu công tác, vật tư dự phòng và nhà thầu trên CMMS.",en:"Plan work, track work orders, spare parts and contractors in the CMMS."}}],knowledge:{vi:["IEC 61724-1 về giám sát hiệu suất hệ thống quang điện: PR, sản lượng chuẩn và sản lượng mảng.","IEC 62446-1 về thử nghiệm, hồ sơ và bảo trì hệ thống PV nối lưới: đo Voc, Isc, điện trở cách điện, đường I-V.","Bộ tiêu chuẩn IEC 61400 về tuabin gió: thiết kế, đo đường cong công suất và khả dụng.","Luật Điện lực số 61/2024/QH15 và Quy chuẩn kỹ thuật quốc gia về an toàn điện QCVN 01:2020/BCT.","Nguyên lý inverter, MPPT, bảo vệ DC (cầu chì string, dao cách ly) và nguy cơ hồ quang DC.","NFPA 70E và nguyên tắc đánh giá rủi ro hồ quang điện, lựa chọn PPE."],en:["IEC 61724-1 on PV system performance monitoring: PR, reference yield and array yield.","IEC 62446-1 on testing, documentation and maintenance of grid-connected PV: Voc, Isc, insulation resistance, I-V curves.","The IEC 61400 series on wind turbines: design, power curve measurement and availability.","Electricity Law No. 61/2024/QH15 and the national electrical safety regulation QCVN 01:2020/BCT.","Inverter and MPPT principles, DC protection (string fuses, isolators) and DC arc hazards.","NFPA 70E and the principles of arc flash risk assessment and PPE selection."]},tools:["Hệ thống SCADA và bảng giám sát nhà máy","Máy đo đường cong I-V","Camera nhiệt và drone kiểm tra","Đồng hồ đo điện trở cách điện","Ampe kìm DC","Phần mềm quản lý bảo trì (CMMS)"],kpis:{vi:["Hệ số hiệu suất PR hiệu chỉnh nhiệt độ so với cam kết thiết kế.","Hệ số khả dụng kỹ thuật của nhà máy (mục tiêu từ 99%).","Thời gian trung bình khắc phục sự cố (MTTR).","Số sự cố an toàn, vi phạm khóa thẻ (mục tiêu bằng 0)."],en:["Temperature-corrected PR against the design commitment.","Technical availability of the plant (target 99% or higher).","Mean time to repair (MTTR).","Safety incidents and lockout violations (target zero)."]},day:[{time:"06:00",vi:"Nhận ca, kiểm tra SCADA, cảnh báo đêm và lệnh điều độ trong ngày.",en:"Take over the shift and check SCADA, overnight alarms and today's dispatch orders."},{time:"08:00",vi:"Phân tích dòng các string, so sánh giữa inverter và lập danh sách bất thường.",en:"Analyze string currents, compare inverters and list anomalies."},{time:"10:00",vi:"Dẫn đội hiện trường đo I-V, chụp nhiệt, xử lý lỗi theo phiếu công tác và khóa thẻ.",en:"Lead the field team on I-V tests and thermography and fix faults under permit and lockout."},{time:"14:00",vi:"Phối hợp cấp điều độ khi có lệnh giảm công suất và ghi nhận sản lượng bị cắt giảm.",en:"Coordinate with dispatch on curtailment orders and record curtailed energy."},{time:"17:30",vi:"Tính sản lượng, PR, cập nhật CMMS và bàn giao ca.",en:"Calculate energy and PR, update the CMMS and hand over the shift."}],mistakes:{vi:["Kết luận bám bẩn cho một string mất dòng mà không đo kiểm, khiến lỗi hở mạch kéo dài.","Tính PR theo công suất AC, làm hiệu suất bị thổi phồng và che giấu tổn thất.","Rút cầu chì DC khi đang mang tải, gây hồ quang nguy hiểm cho người và thiết bị."],en:["Calling a dead string soiling without measuring, so an open circuit goes unfixed.","Calculating PR on the AC rating, inflating performance and hiding losses.","Pulling a DC fuse under load, creating a dangerous arc for people and equipment."]},career:[{vi:"Kỹ thuật viên vận hành nhà máy năng lượng tái tạo",en:"Renewable plant operations technician"},{vi:"Kỹ sư vận hành & bảo trì",en:"O&M engineer"},{vi:"Trưởng ca, Trưởng nhà máy",en:"Shift supervisor, Plant manager"},{vi:"Giám đốc O&M khu vực",en:"Regional O&M Director"}],glossary:[{term:"PR",vi:"Hệ số hiệu suất: tỷ số giữa sản lượng thực và sản lượng lý thuyết theo công suất DC và bức xạ.",en:"Performance ratio: actual output divided by theoretical output from the DC rating and irradiation."},{term:"POA",vi:"Bức xạ trên mặt phẳng tấm pin, đo bằng nhật xạ kế đặt cùng góc nghiêng với mảng.",en:"Plane-of-array irradiance measured by a pyranometer at the array tilt."},{term:"Voc",vi:"Điện áp hở mạch: điện áp của tấm hoặc string khi không có dòng điện chạy qua.",en:"Open-circuit voltage: module or string voltage when no current flows."},{term:"LOTO",vi:"Khóa thẻ: cách ly nguồn năng lượng, khóa và treo thẻ trước khi làm việc trên thiết bị.",en:"Lockout-tagout: isolating energy, locking and tagging before working on equipment."},{term:"Curtailment",vi:"Cắt giảm công suất: nhà máy phải giảm phát theo lệnh điều độ dù có đủ nắng, gió.",en:"Reducing output on dispatch orders even though sun or wind is available."}],quiz:[{q:{vi:"Nhà máy 10 MWp DC (8 MWac) phát 1200000 kWh trong tháng, bức xạ POA 150 kWh/m2. PR là bao nhiêu?",en:"A 10 MWp DC (8 MWac) plant exports 1200000 kWh in a month with 150 kWh/m2 POA irradiation. What is PR?"},options:{vi:["100%","80%","75%","120%"],en:["100%","80%","75%","120%"]},answer:1,explain:{vi:"PR = 1200000 / (10000 x 150) = 80%; dùng công suất AC 8 MW sẽ cho 100%, sai bản chất.",en:"PR = 1200000 / (10000 x 150) = 80%; using the 8 MW AC rating gives a misleading 100%."}},{q:{vi:"Một string có điện áp gần Voc nhưng dòng bằng 0, điện trở cách điện đạt. Lỗi có khả năng nhất là gì?",en:"A string shows near-Voc voltage but zero current, and insulation is fine. What is the most likely fault?"},options:{vi:["Hở mạch: cầu chì hoặc đầu nối bị đứt","Chạm đất","Bám bẩn","Lỗi MPPT của toàn inverter"],en:["Open circuit: blown fuse or broken connector","Ground fault","Soiling","Inverter-wide MPPT fault"]},answer:0,explain:{vi:"Có áp mà không có dòng nghĩa là mạch bị hở; chạm đất sẽ làm điện trở cách điện giảm.",en:"Voltage without current means the circuit is open; a ground fault would lower insulation resistance."}},{q:{vi:"Cần thay cầu chì string khi trời đang nắng. Quy trình đúng là gì?",en:"A string fuse must be replaced in full sun. What is the correct procedure?"},options:{vi:["Rút ngay khi inverter đang chạy","Đeo găng tay vải rồi rút","Che tấm pin bằng tay","Dừng inverter, mở dao cách ly DC, kiểm tra không dòng, khóa thẻ rồi mới thay"],en:["Pull it while the inverter runs","Wear cotton gloves and pull it","Cover the modules by hand","Stop the inverter, open the DC isolator, verify zero current, lock out, then replace"]},answer:3,explain:{vi:"Ngắt dòng DC khi có tải tạo hồ quang khó dập tắt; phải cách ly, kiểm tra không dòng và khóa thẻ.",en:"Breaking DC under load creates a persistent arc; isolate, verify zero current and lock out first."}},{q:{vi:"Bộ tiêu chuẩn quốc tế nào áp dụng cho tuabin gió?",en:"Which international standard series applies to wind turbines?"},options:{vi:["IEC 61724","ISO 14001","IEC 61400","IEC 62446"],en:["IEC 61724","ISO 14001","IEC 61400","IEC 62446"]},answer:2,explain:{vi:"IEC 61400 là bộ tiêu chuẩn về tuabin gió; IEC 61724 và IEC 62446 dành cho hệ thống quang điện.",en:"IEC 61400 covers wind turbines; IEC 61724 and IEC 62446 are for PV systems."}}],tools_en:["SCADA and plant monitoring dashboard","I-V curve tracer","Thermal cameras and inspection drones","Insulation resistance tester","DC clamp meter","Maintenance management software (CMMS)"]}}})})(window.KKR);
